window.__rgjRes=null; window.__rgjErr=null;
(async () => { try {
  const parse = async (u) => {
    const h = await (await fetch(u)).text();
    const d = new DOMParser().parseFromString(h,'text/html');
    const s = d.querySelector('script[type="application/json"]');
    let props = null, keys = null;
    if (s) { try { const j = JSON.parse(s.textContent); props = j; keys = Object.keys(j.props||{}); } catch(e) { keys = ['unparseable']; } }
    const hrefs = [...d.querySelectorAll('a[href*="/game/"]')].map(a=>a.getAttribute('href'));
    return { len: h.length, hasJson: !!s, keys, hrefCount: hrefs.length, hrefSample: hrefs.slice(0,5),
             jsonStr: s ? s.textContent.length : 0,
             jsonHasContra: s ? /Contra/i.test(s.textContent) : false,
             propsKeysDeep: keys ? keys.join(',') : '' };
  };
  window.__rgjRes = JSON.stringify({ search: await parse('https://retroachievements.org/search?q=Contra'),
                                     list: await parse('https://retroachievements.org/gameList.php?system=7') });
} catch(e){ window.__rgjErr = String(e && e.stack || e); } })();
